const body = $json.body || $json;

const candidateId = body.candidateId || 'cand_demo_reject';
const candidateName = body.name || body.candidateName || 'Ứng viên';
const candidateEmail = body.email || body.candidateEmail || 'test.applicant@company.local';
const jobTitle = body.jobTitle || 'Chuyên viên Công nghệ';
const matchScore = Number(body.matchScore !== undefined ? body.matchScore : 45);
const requireHrApproval = body.requireHrApproval !== undefined ? Boolean(body.requireHrApproval) : false;

const parsed = typeof body.parsedSkillsJson === 'object' && body.parsedSkillsJson !== null ? body.parsedSkillsJson : {};
const rawSkills = (Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0)
  ? [...parsed.coreSkills, ...(Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : [])]
  : (Array.isArray(parsed.skills) ? parsed.skills : (Array.isArray(body.parsedSkillsJson) ? body.parsedSkillsJson : (Array.isArray(body.skills) ? body.skills : [])));

const coreSkills = Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0
  ? parsed.coreSkills
  : (rawSkills.length > 0 ? rawSkills.slice(0, 3) : ['Chuyên môn chung']);
const secondarySkills = Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : (rawSkills.length > 3 ? rawSkills.slice(3) : []);
const systemScaleScore = Number(parsed.systemScaleScore || body.systemScaleScore || 60);
const githubUrl = parsed.githubUrl || body.githubUrl || null;
const skills = rawSkills.length > 0 ? rawSkills : ['Kỹ năng chuyên môn'];
const skillsStr = Array.isArray(skills) ? skills.join(', ') : String(skills);
const companyName = body.companyName || 'Công ty Cổ phần Công nghệ HR Tech Hub';

const senderName = body.senderName || 'Bộ phận Thu hút & Phát triển Nhân tài';
const senderPhone = body.senderPhone || '0901 234 567';
const senderEmail = body.senderEmail || 'recruitment@company.com';

// Phân loại kịch bản (CV_SCREENING vs POST_INTERVIEW)
const stage = (body.stage || body.currentStage || 'CV_SCREENING').toUpperCase();
const isPostInterview = stage.includes('INTERVIEW') || stage.includes('PHỎNG VẤN') || stage.includes('VÒNG 2');
const scenarioCode = isPostInterview ? 'POST_INTERVIEW' : 'CV_SCREENING';

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    requireHrApproval,
    skills,
    coreSkills,
    secondarySkills,
    systemScaleScore,
    githubUrl,
    skillsStr,
    companyName,
    senderName,
    senderPhone,
    senderEmail,
    scenarioCode,
    isPostInterview
  }
}];

const data = $json;
const jobTitle = data.jobTitle || '';
const skillsStr = data.skillsStr || '';
const techContext = (jobTitle + ' ' + skillsStr).toLowerCase();

let careerAdvice;
let suggestedSkills;

if (techContext.includes('front') || techContext.includes('react') || techContext.includes('vue')) {
  careerAdvice = 'Đối với lộ trình phát triển Frontend chuyên sâu, bạn có thể tập trung nâng cao khả năng tối ưu hiệu năng hiển thị (LCP/FID), thiết kế component có tính tái sử dụng cao và bổ sung kiểm thử tự động (Unit/E2E test).';
  suggestedSkills = [
    'Tối ưu hóa Core Web Vitals & Web Performance',
    'Kiến trúc State Management quy mô lớn',
    'Automated Testing (Jest, Playwright) & CI/CD Frontend'
  ];
} else if (techContext.includes('devops') || techContext.includes('cloud') || techContext.includes('k8s')) {
  careerAdvice = 'Để chuẩn bị tốt cho các vị trí Cloud/DevOps quy mô lớn, chúng tôi đề xuất bạn củng cố kiến thức về Infrastructure as Code (Terraform), thiết kế hệ thống quan sát (Observability/Prometheus/Grafana) và bảo mật container.';
  suggestedSkills = [
    'Infrastructure as Code (Terraform, Ansible)',
    'Observability Stack (Prometheus, Grafana, OpenTelemetry)',
    'Kubernetes Security & Service Mesh (Istio)'
  ];
} else {
  careerAdvice = 'Để nâng cao tính cạnh tranh cho các vị trí Backend quy mô lớn, chúng tôi khuyến khích bạn tiếp tục hoàn thiện kiến trúc hệ thống phân tán, xử lý tải cao (High Concurrency) và thực hành xây dựng các dự án mẫu có tích hợp Cache và Message Queue.';
  suggestedSkills = [
    'Thiết kế Microservices & Domain-Driven Design (DDD)',
    'Tối ưu hóa Database (Indexing, Query Optimization)',
    'Distributed Caching (Redis) & Message Queue (Kafka/RabbitMQ)'
  ];
}

return [{
  json: {
    ...data,
    careerAdvice,
    suggestedSkills
  }
}];

const data = $json;
const matchScore = data.matchScore || 0;
const techContext = (data.jobTitle + ' ' + (data.skillsStr || '')).toLowerCase();

let talentPoolTag = 'TALENT_POOL_BACKEND';
if (techContext.includes('devops') || techContext.includes('cloud')) talentPoolTag = 'TALENT_POOL_DEVOPS';
else if (techContext.includes('data') || techContext.includes('ai')) talentPoolTag = 'TALENT_POOL_DATA_AI';
else if (techContext.includes('frontend') || techContext.includes('react')) talentPoolTag = 'TALENT_POOL_FRONTEND';

let candidateLevel = 'Junior';
if (data.systemScaleScore >= 80 || matchScore >= 75) candidateLevel = 'Senior';
else if (data.systemScaleScore >= 65 || matchScore >= 60) candidateLevel = 'Middle';

const detailedTalentTag = `${talentPoolTag}_${candidateLevel}_${matchScore >= 60 ? 'Priority' : 'General'}`;
const talentPoolTier = matchScore >= 70 ? 'PRIORITY_TALENT_POOL' : 'GENERAL_TALENT_POOL';

return [{
  json: {
    ...data,
    talentPoolTag,
    candidateLevel,
    detailedTalentTag,
    talentPoolTier
  }
}];

const data = $json;

const reEngage = new Date();
reEngage.setDate(reEngage.getDate() + 180);
const reEngagementDate = reEngage.toISOString().split('T')[0];
const reEngagementFormatted = reEngage.toLocaleDateString('vi-VN', {
  year: 'numeric',
  month: 'numeric',
  day: 'numeric'
});

return [{
  json: {
    ...data,
    reEngagementDate,
    reEngagementFormatted,
    reEngagementCycleDays: 180
  }
}];

const data = $json;
const candidateId = data.candidateId;

const cxSurveyUrl = `http://localhost:3001/recruitment/cx-feedback?candidateId=${candidateId}`;
const cxStars = [1, 2, 3, 4, 5].map(score => ({
  score,
  label: `${score} Sao`,
  url: `http://localhost:3001/recruitment/cx-feedback?candidateId=${candidateId}&score=${score}`
}));

return [{
  json: {
    ...data,
    cxSurveyUrl,
    cxStars
  }
}];

const intake = $('Candidate Experience (CX) Survey Generator').first()?.json || $json;

const candidateId = intake.candidateId;
const candidateName = intake.candidateName;
const candidateEmail = intake.candidateEmail;
const jobTitle = intake.jobTitle;
const matchScore = intake.matchScore;
const skills = intake.skills;
const coreSkills = intake.coreSkills;
const secondarySkills = intake.secondarySkills;
const systemScaleScore = intake.systemScaleScore;
const githubUrl = intake.githubUrl;
const companyName = intake.companyName;
const senderName = intake.senderName;
const senderPhone = intake.senderPhone;
const senderEmail = intake.senderEmail;
const scenarioCode = intake.scenarioCode;
const isPostInterview = intake.isPostInterview;
const careerAdvice = intake.careerAdvice;
const suggestedSkills = intake.suggestedSkills;
const talentPoolTag = intake.talentPoolTag;
const candidateLevel = intake.candidateLevel;
const detailedTalentTag = intake.detailedTalentTag;
const talentPoolTier = intake.talentPoolTier;
const reEngagementDate = intake.reEngagementDate;
const reEngagementFormatted = intake.reEngagementFormatted;
const cxSurveyUrl = intake.cxSurveyUrl;
const cxStars = intake.cxStars;

const archivedAt = new Date().toISOString();

const emailSubject = `Thư phản hồi hồ sơ ứng tuyển vị trí ${jobTitle} – ${companyName}`;

const suggestedSkillsHtml = (suggestedSkills || []).map(s => `<li style="margin-bottom: 6px; color: #334155;"><strong>${s}</strong></li>`).join('');

const cxSurveyBlock = `
<div style="margin: 25px 0; padding: 20px; background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 8px; text-align: center;">
  <div style="font-weight: 700; color: #166534; font-size: 14px; margin-bottom: 8px;">🌟 ĐÁNH GIÁ TRẢI NGHIỆM TUYỂN DỤNG CỦA BẠN</div>
  <p style="font-size: 13px; color: #15803d; margin: 0 0 12px 0;">Ý kiến của bạn giúp chúng tôi cải thiện quy trình tuyển dụng tốt hơn mỗi ngày:</p>
  <div style="display: flex; justify-content: center; gap: 8px; flex-wrap: wrap;">
    <a href="${cxSurveyUrl}&score=5" style="display: inline-block; padding: 8px 14px; background: #22c55e; color: #ffffff; text-decoration: none; border-radius: 6px; font-weight: 600; font-size: 12px;">⭐⭐⭐⭐⭐ Xuất sắc</a>
    <a href="${cxSurveyUrl}&score=4" style="display: inline-block; padding: 8px 14px; background: #16a34a; color: #ffffff; text-decoration: none; border-radius: 6px; font-weight: 600; font-size: 12px;">⭐⭐⭐⭐ Tốt</a>
    <a href="${cxSurveyUrl}&score=3" style="display: inline-block; padding: 8px 14px; background: #ca8a04; color: #ffffff; text-decoration: none; border-radius: 6px; font-weight: 600; font-size: 12px;">⭐⭐⭐ Bình thường</a>
  </div>
</div>`;

const emailHtml = `
<!DOCTYPE html>
<html>
<body style="font-family: Arial, sans-serif; line-height: 1.6; color: #1e293b; max-width: 650px; margin: 0 auto; padding: 20px;">
  <div style="border-bottom: 2px solid #0070f3; padding-bottom: 12px; margin-bottom: 20px;">
    <h2 style="color: #0f172a; margin: 0;">${companyName}</h2>
    <div style="color: #64748b; font-size: 13px;">Bộ phận Thu hút & Phát triển Nhân tài</div>
  </div>

  <p>Chào bạn <strong>${candidateName}</strong>,</p>

  <p>Lời đầu tiên, Hội đồng Tuyển dụng tại <strong>${companyName}</strong> xin chân thành cảm ơn bạn đã dành thời gian và sự quan tâm đối với vị trí <strong>${jobTitle}</strong>.</p>

  <p>Sau khi xem xét kỹ lưỡng hồ sơ, chúng tôi đánh giá cao kinh nghiệm và tiềm năng của bạn. Tuy nhiên, ở giai đoạn hiện tại, tiêu chí tuyển dụng của vị trí này đòi hỏi mức độ phù hợp cao hơn về một số yêu cầu kỹ thuật đặc thù, vì vậy chúng tôi rất tiếc chưa thể đồng hành cùng bạn vào vòng tiếp theo.</p>

  <div style="background: #f8fafc; border-left: 4px solid #0070f3; padding: 16px; margin: 20px 0; border-radius: 0 8px 8px 0;">
    <div style="font-weight: 700; color: #0f172a; margin-bottom: 8px;">💡 GỢI Ý PHÁT TRIỂN NGHỀ NGHIỆP DÀNH RIÊNG CHO BẠN:</div>
    <p style="margin: 0 0 10px 0; color: #475569; font-size: 13px;">${careerAdvice}</p>
    <div style="font-weight: 600; color: #334155; font-size: 13px; margin-bottom: 6px;">Các kỹ năng trọng tâm nên củng cố:</div>
    <ul style="margin: 0; padding-left: 20px; font-size: 13px;">
      ${suggestedSkillsHtml}
    </ul>
  </div>

  <div style="background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 8px; padding: 14px; margin: 20px 0; font-size: 13px; color: #1e40af;">
    <strong>📦 LƯU TRỮ MẠNG LƯỚI NHÂN TÀI (TALENT POOL):</strong><br>
    Hồ sơ của bạn đã được đưa vào kho lưu trữ nhân tài ưu tiên (Mã: <code>${detailedTalentTag}</code>). Chúng tôi sẽ chủ động liên hệ lại với bạn vào chu kỳ tuyển dụng tiếp theo (dự kiến ngày <strong>${reEngagementFormatted}</strong>) khi có cơ hội phù hợp.
  </div>

  ${cxSurveyBlock}

  <p>Chúc bạn luôn gặt hái nhiều thành công rực rỡ trên con đường sự nghiệp!</p>

  <div style="margin-top: 30px; border-top: 1px solid #e2e8f0; padding-top: 15px; font-size: 13px; color: #64748b;">
    <strong>${senderName}</strong><br>
    ${companyName}<br>
    Hotline: ${senderPhone} | Email: ${senderEmail}
  </div>
</body>
</html>`;

const candidateEmailPacket = {
  to: candidateEmail,
  subject: emailSubject,
  html: emailHtml
};

const internalSquadBriefing = {
  candidateId,
  candidateName,
  candidateEmail,
  jobTitle,
  matchScore,
  scenarioCode,
  talentPoolTag,
  candidateLevel,
  detailedTalentTag,
  reEngagementDate,
  archivedAt
};

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    skills,
    coreSkills,
    secondarySkills,
    systemScaleScore,
    githubUrl,
    careerAdvice,
    scenarioCode,
    talentPoolTier,
    talentPoolTag,
    detailedTalentTag,
    reEngagementDate,
    candidateLevel,
    suggestedSkills,
    archivedAt,
    summaryForBackend: `[TALENT POOL ARCHIVED]: ${detailedTalentTag} - Chu kỳ tái liên hệ: ${reEngagementFormatted}.`,
    candidateEmailPacket,
    internalSquadBriefing
  }
}];

const data = $('Phân Loại Kịch Bản & Soạn Thư Từ Chối').first().json;

return [{
  json: {
    channel: 'HR_TALENT_POOL_REGISTRY',
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    jobTitle: data.jobTitle,
    matchScore: data.matchScore,
    scenario: data.scenarioCode,
    scenarioTitle: data.scenarioTitle,
    talentPoolTier: data.talentPoolTier,
    talentPoolTag: data.talentPoolTag,
    careerAdvice: data.careerAdvice,
    suggestedSkills: data.suggestedSkills,
    archivedAt: data.archivedAt,
    retentionPolicy: data.scenarioCode === 'TOP_TALENT' ? 'Ưu tiên liên hệ lại ngay khi có đợt tuyển dụng mới' : 'Lưu trữ hồ sơ dự phòng chuyên môn',
    status: 'RECORDED_IN_TALENT_POOL'
  }
}];

const data = $json;
return [{
  json: {
    success: true,
    channel: '#talent-pool-archive',
    alertType: 'TALENT_POOL_INGESTION',
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    jobTitle: data.jobTitle,
    talentTag: data.detailedTalentTag || data.talentPoolTag,
    candidateLevel: data.candidateLevel,
    reEngagementDate: data.reEngagementDate,
    cxSurveyUrl: data.cxSurveyUrl,
    timestamp: new Date().toISOString()
  }
}];

const data = $('Phân Loại Kịch Bản & Soạn Thư Từ Chối').first().json;
const backendSyncResult = $json;

return [{
  json: {
    success: true,
    action: data.requireHrApproval ? "TALENT_POOL_ARCHIVED_PENDING_HR_APPROVAL" : "CANDIDATE_REJECTION_AND_TALENT_POOL_ARCHIVED",
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    jobTitle: data.jobTitle,
    matchScore: data.matchScore,
    scenario: {
      code: data.scenarioCode,
      title: data.scenarioTitle,
      tier: data.talentPoolTier
    },
    talentPoolTag: data.talentPoolTag,
    tieBreakRuleApplied: data.tieBreakRuleApplied,
    careerAdvice: data.careerAdvice,
    suggestedSkills: data.suggestedSkills,
    emailDelivery: {
      recipient: data.candidateEmail,
      subject: data.emailSubject,
      smtpStatus: data.requireHrApproval ? "HELD_FOR_HR_REVIEW" : "DISPATCHED"
    },
    backendSync: {
      status: backendSyncResult?.id ? "SYNCED_TO_DATABASE" : "STANDALONE_SIMULATED",
      updatedCandidateId: backendSyncResult?.id || data.candidateId
    },
    archivedAt: data.archivedAt
  }
}];
